<script setup lang="ts">
import {ref,watch,computed} from 'vue';import {useRoute} from 'vue-router';import {api} from '../api';import {useAuth} from '../stores/auth';import DataPanel from '../components/DataPanel.vue';import BankWorkspace from '../components/BankWorkspace.vue';import AppraisalWorkspace from '../components/AppraisalWorkspace.vue';import DocumentViewer from '../components/DocumentViewer.vue';import {ArrowLeft,Upload,Share2,FileText,Play,AlertTriangle,Eye,Archive,CheckCircle2,X} from 'lucide-vue-next';
const route=useRoute(),auth=useAuth(),file=ref<any>(),analysis=ref<any>(),module=ref('bank'),tab=ref('overview'),error=ref(''),success=ref(''),busy=ref(false),activity=ref<any[]>([]),history=ref<any[]>([]),members=ref<any[]>([]),report=ref<any>(),source=ref<any>(),shareUser=ref(''),note=ref(''),visibility=ref('shared'),upload=ref<File>(),fictional=ref(false),replace=ref(''),edit=ref(false),rename=ref(''),draft=ref<any>({statement_months:12,account_type:'business',expense_method:'standard',expense_ratio:'40.00',appraisal_form:'1004',units:1,occupancy:'investment',rent:'3300.00',pitia:'3000.00',loan_amount:'250000.00',value:'325000.00'}),decision=ref<any>(),reason=ref(''),decisionValue=ref('');
const samplePreview=ref(false);const endpoint=computed(()=>'/api/files/'+route.params.id);const restricted=computed(()=>file.value?.permissions.restricted);const tabs=computed(()=>{const common=['documents','notes','activity','reports'];return module.value==='bank'?['overview','transactions','income','transfers','nsf',...(restricted.value?['sustainability','integrity']:[]),'inputs',...common]:module.value==='appraisal'?['overview','property','comparables','rent','photos','findings','revisions','inputs',...common]:['overview','scenarios','leases','guidelines','inputs',...common]});const section=computed(()=>analysis.value?.data?.[module.value]?.[tab.value]);const findings=computed(()=>Array.isArray(section.value)?section.value:[]);const sourceVersion=computed(()=>file.value?.documents.flatMap((d:any)=>d.versions).find((v:any)=>v.id===source.value?.document_version_id));
async function load(){const scope=endpoint.value;try{const result=await api(scope);const [a,events,reviews,candidates]=await Promise.all([api(scope+'/analysis'),api(scope+'/activity'),result.permissions.review?api(scope+'/review-history'):Promise.resolve([]),result.permissions.share?api(scope+'/share-candidates'):Promise.resolve([])]);if(scope!==endpoint.value)return;file.value=result;rename.value=result.name;draft.value={...draft.value,...result.draft_inputs};analysis.value=a.analysis;activity.value=events;history.value=reviews;members.value=candidates;}catch(e:any){if(scope!==endpoint.value)return;error.value=e.message;if([401,403,404].includes(e.status)){file.value=null;analysis.value=null;source.value=null;report.value=null}}}
watch(()=>route.params.id,async()=>{file.value=null;analysis.value=null;source.value=null;report.value=null;activity.value=[];history.value=[];members.value=[];samplePreview.value=false;upload.value=undefined;replace.value='';fictional.value=false;note.value='';visibility.value='shared';shareUser.value='';decision.value=null;edit.value=false;error.value='';success.value='';busy.value=false;draft.value={statement_months:12,account_type:'business',expense_method:'standard',expense_ratio:'40.00',appraisal_form:'1004',units:1,occupancy:'investment',rent:'3300.00',pitia:'3000.00',loan_amount:'250000.00',value:'325000.00'};await load();if(file.value)module.value=file.value.module;},{immediate:true});
async function action(fn:()=>Promise<any>,message:string){const scope=endpoint.value;busy.value=true;error.value='';success.value='';try{await fn();if(scope!==endpoint.value)return;success.value=message;await load()}catch(e:any){if(scope===endpoint.value)error.value=e.message}finally{if(scope===endpoint.value)busy.value=false}}
async function sample(){await action(()=>api(endpoint.value+'/sample-analysis','POST',{idempotency_key:'fictional-v1'}),'Sample job requested. Refresh status when the queue completes.');}
async function addDocument(){if(!upload.value)return;const fd=new FormData();fd.append('file',upload.value);fd.append('fictional_sample',fictional.value?'1':'0');await action(()=>api(replace.value?'/api/documents/'+replace.value+'/versions':endpoint.value+'/documents','POST',fd),'Original preserved in quarantine. Start processing from the connected review.');}
async function previewReport(){const scope=endpoint.value;try{const next=await api(scope+'/reports/'+module.value);if(scope===endpoint.value)report.value=next}catch(e:any){if(scope===endpoint.value)error.value=e.message}}
function showSource(e:any){source.value=e||analysis.value?.data.source}
function findingDecision(f:any,kind='finding'){decision.value={...f,kind};reason.value='';decisionValue.value=kind==='finding'?'needs_review':'eligible_deposit'}
async function saveDecision(){await action(()=>api(endpoint.value+'/overrides','POST',{target_id:decision.value.id,kind:decision.value.kind,value:decisionValue.value,reason:reason.value}),'Decision recorded without modifying original evidence.');decision.value=null}
function label(s:string){return ({nsf:'NSF / overdrafts',income:'Income summary',integrity:'Integrity findings',inputs:'Draft inputs'} as Record<string,string>)[s]||s.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase())}
</script>
<template><div><RouterLink to="/dashboard" class="back-link"><ArrowLeft :size="16"/>All loan files</RouterLink><p v-if="error" role="alert" class="alert error">{{error}}</p><p v-if="success" role="status" class="alert success">{{success}}</p><template v-if="file"><div class="page-heading"><div><div class="inline"><span class="badge" :class="file.is_demo?'amber':'teal'">{{file.is_demo?'FICTIONAL DEMO FILE':'UPLOAD WORKSPACE'}}</span><span class="badge">{{file.archived_at?'Archived':file.status.replace('_',' ')}}</span></div><h1>{{file.name}}</h1><p class="muted">{{file.borrower.name}} · {{file.reference||'No reference'}} · {{auth.membership?.role}}</p></div><div class="actions"><button v-if="file.permissions.edit" @click="edit=!edit">Edit file</button><button v-if="file.is_demo&&file.permissions.edit" class="primary" :disabled="busy" @click="sample"><Play :size="16"/>Load sample analysis</button><button :disabled="busy" @click="load">Refresh status</button></div></div><div v-if="edit" class="card form-stack"><label>File name<input v-model="rename"/></label><div class="actions"><button @click="action(()=>api(endpoint,'PATCH',{name:rename}),'File updated.')">Save name</button><button @click="action(()=>api(endpoint,'PATCH',{archived:!file.archived_at}),file.archived_at?'File restored.':'File archived.')"><Archive :size="16"/>{{file.archived_at?'Restore file':'Archive file'}}</button><button @click="action(()=>api('/api/organizations/'+file.organization_id+'/borrowers/'+file.borrower.id,'PATCH',file.borrower),'Borrower updated.')">Save borrower edits</button></div><label>Borrower name<input v-model="file.borrower.name"/></label><label>Borrower email<input v-model="file.borrower.email" type="email"/></label><label>Borrower phone<input v-model="file.borrower.phone"/></label></div><div v-if="samplePreview" class="notice"><AlertTriangle :size="22"/><div><strong>{{analysis?'Sample analysis loaded — fictional fixtures only':'Uploaded — analysis integration pending.'}}</strong><p>{{analysis?'These results are not generated from your uploads. This sample action runs no extraction, AI, fraud detection or financial calculations.':'Uploads never trigger sample analysis or imply successful processing. Sample results require a fictional demo file and the separate action.'}}</p></div></div><div v-if="file.runs.length" class="run-strip"><span v-for="r in file.runs" class="badge">Sample run {{r.id.slice(0,8)}} · {{r.status}} · {{r.stage}}</span></div><div class="module-switch" aria-label="Analysis module"><button v-for="[key,name] in [['bank','Bank Statement Income & Integrity'],['appraisal','Appraisal Review'],['dscr','Rental Income / DSCR']]" :class="{active:module===key}" @click="module=key;tab='overview';source=null">{{name}}</button></div><label v-if="file.is_demo&&file.permissions.review" class="check"><input type="checkbox" v-model="samplePreview"/>Explicit Phase 1 fictional sample interface (not upload processing)</label><BankWorkspace v-if="module==='bank'&&!samplePreview" :file="file" @refresh="load"/><AppraisalWorkspace v-else-if="module!=='bank'&&!samplePreview" :file="file" :module="module" @refresh="load"/><template v-else><div class="tabs" role="tablist"><button v-for="t in tabs" role="tab" :aria-selected="tab===t" :class="{active:tab===t}" @click="tab=t;source=null">{{label(t)}}</button></div><div :class="['review-layout',{'with-source':source}]" role="tabpanel"><section class="content-card"><div class="section-heading"><h2>{{label(tab)}}</h2><span v-if="analysis&&!['documents','notes','activity','inputs'].includes(tab)" class="badge amber">SAMPLE DATA</span></div>
<template v-if="tab==='documents'"><p class="muted">Private originals are immutable. Replacement adds a version, never overwrites evidence.</p><form v-if="file.permissions.edit" class="upload-form form-stack" @submit.prevent="addDocument"><label>Fictional source document (PDF, PNG, JPG · max 20 MB)<input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="upload=($event.target as HTMLInputElement).files?.[0]" required/></label><label>Version target<select v-model="replace"><option value="">New document</option><option v-for="d in file.documents.filter((x:any)=>x.category!=='fixture')" :value="d.id">New version of {{d.title}}</option></select></label><label class="check"><input type="checkbox" v-model="fictional" required/>I confirm this is fictional sample data, not a real financial document.</label><button class="primary" :disabled="busy"><Upload :size="16"/>Upload private sample</button><small>Scanner is not configured. Uploads remain in private quarantine, are not certified clean, and are sample-only.</small></form><div v-for="d in file.documents" class="document-card"><h3><FileText :size="18"/>{{d.title}}</h3><div v-for="v in d.versions" class="version-row"><div><strong>Version {{v.version}} · {{v.original_name}}</strong><small>{{v.status}} · {{v.bytes}} bytes · Scan: {{v.scan_status}}</small><code>SHA-256 {{v.sha256}}</code></div><div class="actions"><button @click="source={document_version_id:v.id,page:1}"><Eye :size="15"/>Preview</button><a class="button" :href="'/api/document-versions/'+v.id+'/content?download=1'">Original</a></div></div></div><p v-if="!file.documents.length" class="empty-state">No documents uploaded yet.</p></template>
<template v-else-if="tab==='inputs'"><div class="alert">Saved drafts only. Changing these values does not run financial or document analysis.</div><form class="form-grid" @submit.prevent="action(()=>api(endpoint,'PATCH',{draft_inputs:draft}),'Draft inputs saved; no calculation was performed.')"><template v-if="module==='bank'"><label>Statement history<select v-model="draft.statement_months"><option :value="12">12 months</option><option :value="24">24 months</option></select></label><label>Account type<select v-model="draft.account_type"><option value="personal">Personal</option><option value="business">Business</option></select></label><label>Expense approach<select v-model="draft.expense_method"><option value="standard">Standard (draft)</option><option value="custom">Custom (draft)</option></select></label><label>Expense ratio (%)<input v-model="draft.expense_ratio" type="number" min="0" max="100" step="0.01"/></label><p class="data-wide muted">Business initial request: two business bank statements. Full 12/24-month coverage is a later processing workflow. NSF events and fee counts are separate.</p></template><template v-else-if="module==='appraisal'"><label>Appraisal form<select v-model="draft.appraisal_form"><option v-for="f in ['1004','1025','1007','216']">{{f}}</option></select></label><label>Units<input v-model.number="draft.units" type="number" min="1" max="4"/></label><label>Occupancy (independent of form)<select v-model="draft.occupancy"><option value="owner_occupied">Owner occupied</option><option value="second_home">Second home</option><option value="investment">Investment</option></select></label></template><template v-else><label>Monthly rent ($)<input v-model="draft.rent" type="number" min="0" step="0.01"/></label><label>Monthly PITIA ($)<input v-model="draft.pitia" type="number" min="0" step="0.01"/></label><label>Loan amount ($)<input v-model="draft.loan_amount" type="number" min="0" step="0.01"/></label><label>Property value ($)<input v-model="draft.value" type="number" min="0" step="0.01"/></label><p class="data-wide muted">This historical draft does not run financial or document analysis. Actual validated DSCR/LTV is in connected review. Fixed sample examples: 3300 ÷ 3000 = 1.10; 2850 ÷ 3000 = 0.95.</p></template><button v-if="file.permissions.edit" class="primary" :disabled="busy">Save draft inputs</button><p v-else class="muted">Your role has read-only draft access.</p></form></template>
<template v-else-if="tab==='notes'"><div v-for="n in file.notes" class="note-card"><span class="badge">{{n.visibility}}</span><p>{{n.body}}</p><small>Member {{n.user_id}} · {{new Date(n.created_at).toLocaleString('en-US',{timeZone:'Asia/Dhaka'})}} (Dhaka)</small></div><form v-if="auth.membership?.role!=='viewer'" class="form-stack" @submit.prevent="action(()=>api(endpoint+'/notes','POST',{body:note,visibility:file.permissions.review?visibility:'shared'}),'Note added.').then(()=>note='')"><label>Add note<textarea v-model="note" required maxlength="5000"/></label><label v-if="restricted">Visibility<select v-model="visibility"><option value="shared">Shared with authorized file users</option><option value="internal">Internal reviewers only</option></select></label><button class="primary" :disabled="busy">Add note</button></form></template>
<template v-else-if="tab==='activity'"><div v-for="a in activity" class="activity-row"><CheckCircle2 :size="17"/><div><strong>{{a.action.replaceAll('.',' · ')}}</strong><small>Member {{a.actor_id||'system'}} · {{new Date(a.created_at).toLocaleString('en-US',{timeZone:'Asia/Dhaka'})}} (Dhaka)</small></div></div></template>
<template v-else-if="tab==='reports'"><div class="empty-state"><FileText :size="40"/><h3>Review a role-scoped sample report</h3><p>Open findings remain visible for review and do not block fictional sample previews. This historical preview is not a generated report; use connected review for actual exports.</p><button class="primary" :disabled="!analysis" @click="previewReport">Open sample report preview</button></div></template>
<template v-else-if="!analysis"><div class="empty-state"><FileText :size="40"/><h3>No analysis has run.</h3><p>Upload fictional documents in the Documents tab. To explore the interface, create a fictional demo file and select “Load sample analysis”.</p></div></template>
<template v-else-if="['integrity','findings','photos'].includes(tab)"><article v-for="f in findings" class="finding-card"><div class="inline"><span class="badge" :class="f.severity==='high'?'red':'amber'">{{f.severity||'sample'}}</span><span class="badge">{{f.status}}</span></div><h3>{{f.title}}</h3><p>{{f.observation}}</p><div class="actions"><button @click="showSource(f.source)">Review beside source</button><button v-if="file.permissions.review&&f.id" @click="findingDecision(f)">Record review decision</button></div></article></template>
<template v-else-if="tab==='transactions'"><div class="table-wrap"><table><thead><tr><th>Date / description</th><th>Amount</th><th>Suggested classification</th><th>Evidence</th></tr></thead><tbody><tr v-for="tx in section"><td>{{tx.date}}<small>{{tx.description}}</small></td><td>${{tx.amount}}</td><td>{{tx.classification}}<small>Sample suggestion, not extraction</small></td><td><button @click="showSource(tx.source)">Source</button><button v-if="file.permissions.review" @click="findingDecision(tx,'classification')">Reclassify sample</button></td></tr></tbody></table></div></template>
<template v-else><DataPanel :data="section||{notice:'No fixture entries for this section.'}"/><button class="secondary" v-if="analysis" @click="showSource(null)">View fictional source evidence</button></template>
<div v-if="file.permissions.review&&history.length" class="review-history"><h3>Reviewer decision history</h3><p class="micro">Append-only decisions. Evidence, sample suggestions and snapshots stay separate.</p><div v-for="h in history" class="note-card"><DataPanel :data="typeof h.data==='string'?JSON.parse(h.data):h.data"/></div></div>
</section><aside v-if="source" class="source-pane"><div class="section-heading"><h3>Source evidence</h3><button aria-label="Close source" class="icon-btn" @click="source=null"><X :size="18"/></button></div><p class="micro">{{source.excerpt||'Preserved original version'}} · Page {{source.page||1}}</p><DocumentViewer v-if="sourceVersion" :version="sourceVersion" :page="source.page" :region="source.region"/><p v-else class="alert">Source version unavailable.</p></aside></div>
</template><section v-if="!samplePreview" class="card spaced"><details><summary>Shared file notes and audit history</summary><article v-for="n in file.notes" class="note-card"><span class="badge">{{n.visibility}}</span><p>{{n.body}}</p><small>Member {{n.user_id}} · {{new Date(n.created_at).toLocaleString('en-US',{timeZone:'Asia/Dhaka'})}} (Dhaka)</small></article><p v-if="!file.notes.length">No shared file notes yet.</p><form v-if="auth.membership?.role!=='viewer'" class="form-stack" @submit.prevent="action(()=>api(endpoint+'/notes','POST',{body:note,visibility:file.permissions.review?visibility:'shared'}),'Shared file note added.').then(()=>note='')"><label>Shared file note<textarea v-model="note" maxlength="5000" required/></label><label v-if="file.permissions.review">Visibility<select v-model="visibility"><option value="shared">Shared with authorized file users</option><option value="internal">Internal reviewers only</option></select></label><button :disabled="busy">Save file note</button></form><h3>Authorized file activity</h3><DataPanel :data="activity"/><h3 v-if="file.permissions.review">Reviewer history</h3><DataPanel v-if="file.permissions.review" :data="history"/></details></section><section v-if="!samplePreview&&!file.permissions.review" class="card spaced"><details><summary>Shared private originals</summary><p>Original access follows current role and clean scan verdict. Sharing never exposes internal appraisal analysis.</p><form v-if="file.permissions.upload" class="form-stack" @submit.prevent="addDocument"><label>Private PDF/JPEG/PNG<input type="file" accept=".pdf,.png,.jpg,.jpeg" required @change="upload=($event.target as HTMLInputElement).files?.[0]"/></label><label v-if="file.permissions.edit">Version target<select v-model="replace"><option value="">New original</option><option v-for="d in file.documents.filter((d:any)=>d.category!=='fixture')" :value="d.id">New immutable version of {{d.title}}</option></select></label><label v-if="file.is_demo"><input type="checkbox" v-model="fictional"/>This upload is fictional (local/testing only)</label><button :disabled="busy">Preserve private original</button></form><article v-for="d in file.documents" class="document-card"><h3>{{d.title}}</h3><div v-for="v in d.versions"><span>Version {{v.version}} · {{v.original_name}} · {{v.scan_status}}</span><a class="button" :href="'/api/document-versions/'+v.id+'/content'">Authorized original</a></div></article></details></section><section class="card sharing-card" v-if="file.permissions.share"><h2><Share2 :size="20"/>File-specific sharing</h2><p class="muted">Only members of this organization. Sharing never elevates a role or reveals restricted reviewer data.</p><form class="inline" @submit.prevent="action(()=>api(endpoint+'/shares','POST',{user_id:Number(shareUser)}),'File shared with selected member.')"><label>Member<select v-model="shareUser" required><option value="">Select a member</option><option v-for="m in members.filter(m=>m.user_id!==auth.user.id)" :value="m.user_id">{{m.user.name}} · {{m.role}}</option></select></label><button :disabled="busy" class="primary">Share file</button></form><div v-for="s in file.shares" class="version-row"><span>Member {{s.user_id}} · {{s.revoked_at?'Revoked':'Active'}}</span><button v-if="!s.revoked_at" @click="action(()=>api(endpoint+'/shares/'+s.id,'DELETE'),'Share revoked. Subsequent file/document requests will be denied unless another independent grant applies.')">Revoke</button></div></section></template><p v-else-if="!error" role="status">Loading loan file…</p></div>
<div v-if="report" class="modal-backdrop" @click.self="report=null"><section class="modal report-modal" v-focus-trap="()=>report=null" role="dialog" aria-modal="true" aria-label="Sample report preview"><div class="section-heading"><h2>{{report.title}}</h2><button @click="report=null">Close</button></div><p class="alert warning">{{report.notice}}</p><h3>{{report.borrower}} · {{report.file}}</h3><small>Run {{report.run_id}} · Fictional ruleset version {{report.ruleset_version}}</small><DataPanel :data="report.data"/><p class="muted">{{report.downloads}}</p></section></div>
<div v-if="decision" class="modal-backdrop" @click.self="decision=null"><section class="modal" v-focus-trap="()=>decision=null" role="dialog" aria-modal="true" aria-label="Record reviewer decision"><h2>Record sample review decision</h2><p>Original evidence and suggestions are never overwritten.</p><form class="form-stack" @submit.prevent="saveDecision"><label>Decision<select v-model="decisionValue"><template v-if="decision.kind==='finding'"><option>needs_review</option><option>acknowledged</option><option>resolved</option><option>dismissed</option></template><template v-else><option>eligible_deposit</option><option>excluded_transfer</option><option>excluded_non_income</option><option>bank_fee</option></template></select></label><label>Reason (required)<textarea v-model="reason" required minlength="5" maxlength="2000"/></label><div class="actions"><button type="button" @click="decision=null">Cancel</button><button class="primary" :disabled="busy">Save decision</button></div></form></section></div></template>
